# 【算法思路】计算向量正交投影、垂直残差分量，并将原向量分解为平行与垂直两部分。
import numpy as np

# 计算 v 在非零基向量 onto 方向上的标量投影并返回投影向量
def project(v: np.ndarray, onto: np.ndarray) -> np.ndarray:
    denom = np.dot(onto, onto)
    if denom == 0:
        raise ValueError('onto vector cannot be zero')
    scalar = np.dot(v, onto) / denom
    return scalar * onto

# 用原向量减去投影分量得到正交分量
def orthogonal(v: np.ndarray, onto: np.ndarray) -> np.ndarray:
    return v - project(v, onto)

# 同时返回平行分量与正交分量
def decompose(v: np.ndarray, onto: np.ndarray) -> dict:
    p = project(v, onto)
    return {'parallel': p, 'perpendicular': v - p}

