# 【算法思路】基于阶乘展开通用函数、e^x 与 sin(x) 的泰勒级数近似，并求解达到指定误差的最小阶数。
import math

# 利用在 a 点的各阶导数累加 n 阶泰勒多项式
def taylor_expand(f, derivs: list, a: float, x: float, order: int) -> float:
    result = 0
    for n in range(order + 1):
        term = derivs[n] * (x - a)**n / math.factorial(n)
        result += term
    return result

# 累加幂级数前 order 项近似自然指数
def exp_approx(x: float, order: int) -> float:
    result = 0
    for n in range(order + 1):
        result += x**n / math.factorial(n)
    return result

# 按奇次交错级数近似正弦值
def sin_approx(x: float, order: int) -> float:
    result = 0
    for n in range(order + 1):
        sign = (-1)**n
        result += sign * x**(2*n + 1) / math.factorial(2*n + 1)
    return result

# 递增阶数直至逼近误差小于给定容忍阈值
def find_min_order(f, target_f, a: float, x: float, tolerance: float) -> int:
    for order in range(20):
        approx = f(x, order)
        if abs(approx - target_f(x)) < tolerance:
            return order
    return -1

# 【算法思路】计算矩阵行列式、判定可逆性并求解逆矩阵及单位阵乘积验证误差。
import numpy as np

# 求解行列式并在非奇异时求逆矩阵及 ||A A^-1 - I|| 最大误差
def matrix_analysis(A):
    A = np.asarray(A, dtype=float)
    det = round(float(np.linalg.det(A)), 4)
    if abs(det) <= 1e-10:
        return {"det": 0.0 if abs(det) <= 1e-10 else det, "invertible": False, "inverse": None, "verification": None}
    inv = np.linalg.inv(A)
    verify = round(float(np.max(np.abs(A @ inv - np.eye(A.shape[0])))), 6)
    return {
        "det": det,
        "invertible": True,
        "inverse": [[round(float(v), 6) for v in row] for row in inv],
        "verification": verify,
    }

# 【算法思路】由先验概率、真阳性率和假阳性率结合全概率公式计算条件后验概率。
# 按贝叶斯公式分子除以全概率证据项得到后验 P(A|B)
def bayes_theorem(prior, likelihood, false_positive):
    evidence = likelihood * prior + false_positive * (1 - prior)
    posterior = (likelihood * prior) / evidence if evidence > 0 else 0
    return round(posterior, 4)

