# 【算法思路】对四次多项式执行固定步长梯度下降，追踪迭代轨迹并判断是否已接近驻点收敛。
# 计算四次目标函数值
def f(x):
    return x**4 - 3*x**3 + 2
# 返回目标函数的一阶解析导数
def df(x):
    return 4*x**3 - 9*x**2
# 运行固定步数梯度下降并检查末步导数幅值收敛标志
def gradient_descent(x0, lr, steps):
    x = x0
    history = [x]
    for _ in range(steps):
        x = x - lr * df(x)
        history.append(x)
    return {"x_history": [round(h,4) for h in history], "final_fx": round(f(history[-1]), 6), "converged": abs(df(history[-1])) < 1e-4}

# 【算法思路】计算 ln(1+x) 在零点的交错泰勒级数展开值并分析与真值的绝对截断误差。
import math
# 按 ln(1+x) 交错幂级数累加至第 order 项
def taylor_ln(x, order):
    result = 0
    for n in range(1, order+1):
        result += (-1)**(n+1) * x**n / n
    return round(result, 6)
# 返回多项式近似值、math.log 真值与绝对误差
def taylor_error(x, order):
    approx = taylor_ln(x, order)
    exact = round(math.log(1+x), 6)
    return {"approx": approx, "exact": exact, "error": round(abs(approx - exact), 6)}
